-- ===============================================================
-- Idempotent UPSERT (MERGE) for RSMST_MSTDIAGS
-- Source: code_system_idrg_20260331.tsv (SAB=ICD10_2010_IM, 40,815 rows)
-- Match: diag_id = TSV.CODE2 (no-dot, mis. A001 utk A00.1)
--
-- WHEN MATCHED  : update HANYA valid_code/accpdx/asterisk/im
--                 (preserve diag_desc kalau admin punya translation custom)
-- WHEN NOT MATCH: insert full row (diag_id, diag_desc, icdx, + 4 flag)
--
-- Prereq: 2026_05_20_alter_idrg_add_validation_columns.sql sudah dijalankan.
-- ===============================================================
SET DEFINE OFF;

MERGE INTO rsmst_mstdiags d USING (SELECT 'A00' AS diag_id, 'Cholera' AS diag_desc, 'A00' AS icdx, 0 AS valid_code, 'N' AS accpdx, 0 AS asterisk, 0 AS im FROM dual) src ON (d.diag_id=src.diag_id) WHEN MATCHED THEN UPDATE SET d.valid_code=src.valid_code, d.accpdx=src.accpdx, d.asterisk=src.asterisk, d.im=src.im WHEN NOT MATCHED THEN INSERT (diag_id, diag_desc, icdx, valid_code, accpdx, asterisk, im) VALUES (src.diag_id, src.diag_desc, src.icdx, src.valid_code, src.accpdx, src.asterisk, src.im);
